window.SAOMD_STORIES[410400201]={"id":410400201,"branches":[],"frames":[{"id":1,"order":1,"actions":[{"uid":"410400201:1:1","speaker":"Kirito","text":"What...?","pose":10011508,"background":"bg_11_forest_yui","item":"","illustration":"","speaker_zh":"桐人","text_zh":"什么……？"},{"uid":"410400201:1:2","speaker":"Yui","text":"","pose":20090208,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""},{"uid":"410400201:1:3","speaker":"Asuna","text":"","pose":10020911,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":2,"order":2,"actions":[{"uid":"410400201:2:1","speaker":"Leafa","text":"So Urdr asked you to come here\nand wipe out the Forces of\nDarkness... Is that right?","pose":10030102,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"所以乌尔德让你来这里消灭黑暗势力……是吗？"},{"uid":"410400201:2:2","speaker":"Sinon","text":"","pose":10040202,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":3,"order":3,"actions":[{"uid":"410400201:3:1","speaker":"Alice","text":"...So I take it you know this\ngoddess I speak of.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"……我想你应该认识我说的这位女神吧。"}]},{"id":4,"order":4,"actions":[{"uid":"410400201:4:1","speaker":"Kirito","text":"Uh, yeah, we do.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"呃，是的，我们知道。"},{"uid":"410400201:4:2","speaker":"Yui","text":"","pose":20090203,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""},{"uid":"410400201:4:3","speaker":"Asuna","text":"","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":5,"order":5,"actions":[{"uid":"410400201:5:1","speaker":"Alice","text":"The Goddess of the Spring asked me\nto gather the seven Divine Objects\nspread throughout this world...","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"春天的女神让我收集散布在这个世界上的七个神器......"}]},{"id":6,"order":6,"actions":[{"uid":"410400201:6:1","speaker":"Alice","text":"And to find warriors strong\nenough to destroy the brutes\ndisturbing her realm.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"并找到足够强大的战士来消灭扰乱她王国的野蛮人。"}]},{"id":7,"order":7,"actions":[{"uid":"410400201:7:1","speaker":"Asuna","text":"K-Kirito... What's going on?","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"K-桐人...怎么回事？"},{"uid":"410400201:7:2","speaker":"Kirito","text":"","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410400201:7:3","speaker":"Yui","text":"","pose":20090203,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":8,"order":8,"actions":[{"uid":"410400201:8:1","speaker":"Kirito","text":"If Alice really is an NPC, she\nmust be describing the scenario\nfor an event quest...","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"如果爱丽丝真的是NPC的话，她一定是在描述一个事件任务的场景……"}]},{"id":9,"order":9,"actions":[{"uid":"410400201:9:1","speaker":"Kirito","text":"But coming up with this level of\ndetail for a minor character's\nbackstory is just insane.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"但是为一个小角色的背景故事想出这种程度的细节实在是太疯狂了。"},{"uid":"410400201:9:2","speaker":"Yui","text":"","pose":20090203,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":10,"order":10,"actions":[{"uid":"410400201:10:1","speaker":"Sinon","text":"No kidding. You'd never mistake\nher for a regular NPC...","pose":10040202,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"别开玩笑了。你永远不会把她误认为是普通的 NPC..."},{"uid":"410400201:10:2","speaker":"Leafa","text":"","pose":10030102,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":11,"order":11,"actions":[{"uid":"410400201:11:1","speaker":"Kirito","text":"Maybe...\nAlice is...","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"也许……爱丽丝是……"},{"uid":"410400201:11:2","speaker":"Asuna","text":"","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400201:11:3","speaker":"Yui","text":"","pose":20090203,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":12,"order":12,"actions":[{"uid":"410400201:12:1","speaker":"Alice","text":"So do you know anything about\nthese Divine Objects or not?","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"那你知道这些神器吗？"}]},{"id":13,"order":13,"actions":[{"uid":"410400201:13:1","speaker":"Leafa","text":"Divine Objects...?\nI haven't even heard of\nthat item class before.","pose":10030102,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"神器...？我以前从未听说过该项目类别。"},{"uid":"410400201:13:2","speaker":"Sinon","text":"","pose":10040202,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":14,"order":14,"actions":[{"uid":"410400201:14:1","speaker":"Asuna","text":"Me neither... I know about the\n\"Legendary\" and \"Ancient\" item\nclasses, but this is a new one...","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我也没有……我知道“传奇”和“远古”物品类别，但这是新的……"},{"uid":"410400201:14:2","speaker":"Kirito","text":"","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410400201:14:3","speaker":"Yui","text":"","pose":20090203,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":15,"order":15,"actions":[{"uid":"410400201:15:1","speaker":"Alice","text":"In my world, Divine Objects are a\nset of extremely precious weapons\nand armor.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"在我的世界里，神器是一套极其珍贵的武器和铠甲。"}]},{"id":16,"order":16,"actions":[{"uid":"410400201:16:1","speaker":"Alice","text":"With them missing, I didn't really\nhave much of a choice but to agree\nto help the goddess.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"他们失踪了，我也没有什么选择，只能答应帮助女神。"}]},{"id":17,"order":17,"actions":[{"uid":"410400201:17:1","speaker":"Kirito","text":"Sorry we can't help that much.\nWe don't know anything\nabout them either...","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"抱歉我们帮不了那么多。我们对他们也一无所知..."},{"uid":"410400201:17:2","speaker":"Asuna","text":"","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400201:17:3","speaker":"Yui","text":"","pose":20090203,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":18,"order":18,"actions":[{"uid":"410400201:18:1","speaker":"Alice","text":"What a shame...\nI heard a rumor that I might\nfind one in this area.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"可惜了……我听说这附近可能会找到一个。"}]},{"id":19,"order":19,"actions":[{"uid":"410400201:19:1","speaker":"Alice","text":"But unless we find them and get\nback to our world soon...","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"但是除非我们尽快找到他们并回到我们的世界……"}]},{"id":20,"order":20,"actions":[{"uid":"410400201:20:1","speaker":"???","text":"Grrauuu!!","pose":2,"background":"","item":"","illustration":"","speaker_zh":"？？？","text_zh":"咕咕！！"},{"uid":"410400201:20:2","speaker":"Asuna","text":"","pose":10020911,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400201:20:3","speaker":"Kirito","text":"","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410400201:20:4","speaker":"Yui","text":"","pose":20090208,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":21,"order":21,"actions":[{"uid":"410400201:21:1","speaker":"Kirito","text":"What was that?","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"那是什么？"},{"uid":"410400201:21:2","speaker":"Asuna","text":"","pose":10020911,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":22,"order":22,"actions":[{"uid":"410400201:22:1","speaker":"Alice","text":"It sounds like Amayori\nis back from scouting...\nThat's my dragon.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"看来雨缘侦察回来了……那是我的龙。"}]},{"id":23,"order":23,"actions":[{"uid":"410400201:23:1","speaker":"Amayori","text":"Kgroouu!!\nGrauuu!","pose":2,"background":"bg_11_forest_yui","item":"","illustration":"","speaker_zh":"雨缘","text_zh":"Kgroouu!!格劳！"},{"uid":"410400201:23:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":24,"order":24,"actions":[{"uid":"410400201:24:1","speaker":"Alice","text":"What's that, Amayori?\nYou spotted more enemies...?\nHere we go again...","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"那是什么，雨缘？你发现了更多的敌人......？我们又来了..."}]},{"id":25,"order":25,"actions":[{"uid":"410400201:25:1","speaker":"Kirito","text":"H-Hey! Wait for us!","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"喂、喂！等我们！"},{"uid":"410400201:25:2","speaker":"Asuna","text":"","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400201:25:3","speaker":"Yui","text":"","pose":20090203,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":26,"order":26,"actions":[{"uid":"410400201:26:1","speaker":"Alice","text":"Why?","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"为什么？"}]},{"id":27,"order":27,"actions":[{"uid":"410400201:27:1","speaker":"Kirito","text":"What'd we just tell you after\nour little spar back there?","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我们刚刚在小晶石之后告诉了你什么？"},{"uid":"410400201:27:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400201:27:3","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":28,"order":28,"actions":[{"uid":"410400201:28:1","speaker":"Kirito","text":"If you're taking down monsters,\nyou're in good company with us!","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"如果你是在打倒怪物，那你就和我们有好关系了！"},{"uid":"410400201:28:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":29,"order":29,"actions":[{"uid":"410400201:29:1","speaker":"Alice","text":"So in this world, you call the\nForces of Darkness \"monsters\"...\nVery well.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"所以在这个世界上，你把黑暗势力称为“怪物”……很好。"}]},{"id":30,"order":30,"actions":[{"uid":"410400201:30:1","speaker":"Alice","text":"Come along if you wish.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"你愿意就来吧。"}]},{"id":31,"order":31,"actions":[{"uid":"410400201:31:1","speaker":"Alice","text":"But be warned... If you can't\nkeep up with me and Amayori,\nyou'll get left behind!","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"但是请注意……如果你跟不上我和雨缘，你就会被抛在后面！"}]},{"id":32,"order":32,"actions":[{"uid":"410400201:32:1","speaker":"Kirito","text":"Yeah, we got it!","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"是的，我们知道了！"},{"uid":"410400201:32:2","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400201:32:3","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":33,"order":33,"actions":[{"uid":"410400201:33:1","speaker":"Monster","text":"Gwhuaaaorh!","pose":1,"background":"bg_04_field_flower_snow","item":"","illustration":"","speaker_zh":"怪物","text_zh":"吼啊啊！"},{"uid":"410400201:33:2","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":34,"order":34,"actions":[{"uid":"410400201:34:1","speaker":"Alice","text":"Hyaaah!!","pose":10540101,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"哈啊！！"}]},{"id":35,"order":35,"actions":[{"uid":"410400201:35:1","speaker":"Monster","text":"GRAAAAUUUUHHHH!!","pose":1,"background":"","item":"","illustration":"","speaker_zh":"怪物","text_zh":"咕噜咕噜！！"}]},{"id":36,"order":36,"actions":[{"uid":"410400201:36:1","speaker":"Asuna","text":"Phew...","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"呼……"},{"uid":"410400201:36:2","speaker":"Kirito","text":"","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410400201:36:3","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":37,"order":37,"actions":[{"uid":"410400201:37:1","speaker":"Asuna","text":"Look at Alice... She's amazing!","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"你看爱丽丝……太棒了！"}]},{"id":38,"order":38,"actions":[{"uid":"410400201:38:1","speaker":"Kirito","text":"Yeah... Nothing stands a chance\nagainst those techniques.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"是的……没有什么可以对抗这些技术。"},{"uid":"410400201:38:2","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":39,"order":39,"actions":[{"uid":"410400201:39:1","speaker":"Leafa","text":"That's way beyond the realm of \nregular sword skills, huh?","pose":10030108,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"这已经超出了普通剑技的范畴了吧？"},{"uid":"410400201:39:2","speaker":"Sinon","text":"","pose":10040208,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":40,"order":40,"actions":[{"uid":"410400201:40:1","speaker":"Sinon","text":"Guys! Not exactly the time\nfor a live commentary!","pose":10040208,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"伙计们！还不是现场解说的时间！"}]},{"id":41,"order":41,"actions":[{"uid":"410400201:41:1","speaker":"Monster","text":"GRAAAAOOHHHH!!","pose":1,"background":"","item":"","illustration":"","speaker_zh":"怪物","text_zh":"吼啊啊！"},{"uid":"410400201:41:2","speaker":"Kirito","text":"","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410400201:41:3","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400201:41:4","speaker":"Yui","text":"","pose":20090207,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":42,"order":42,"actions":[{"uid":"410400201:42:1","speaker":"Kirito","text":"Dammit...! This difficulty level\nhas to be a mistake, right?!","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"可恶……！这个难度一定是个错误吧？！"}]},{"id":43,"order":43,"actions":[{"uid":"410400201:43:1","speaker":"Yui","text":"Daddy! According to\nthe database...","pose":20090202,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"爸爸！根据数据库..."}]},{"id":44,"order":44,"actions":[{"uid":"410400201:44:1","speaker":"Yui","text":"This one is even stronger than\nthe ones that Alice defeated\nthe other day!","pose":20090202,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"这个比前几天爱丽丝打败的还要强！"}]},{"id":45,"order":45,"actions":[{"uid":"410400201:45:1","speaker":"Kirito","text":"Seriously?!","pose":100115032,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"认真的吗？！"}]},{"id":46,"order":46,"actions":[{"uid":"410400201:46:1","speaker":"Monster","text":"GRAAAUGH!!!","pose":1,"background":"","item":"","illustration":"","speaker_zh":"怪物","text_zh":"格子！！！"}]},{"id":47,"order":47,"actions":[{"uid":"410400201:47:1","speaker":"Kirito","text":"Hngh...!","pose":100115072,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"哼……！"}]},{"id":48,"order":48,"actions":[{"uid":"410400201:48:1","speaker":"Asuna","text":"Kirito!\nLook out!!","pose":10020908,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"桐人！当心！！"},{"uid":"410400201:48:2","speaker":"Kirito","text":"","pose":100115072,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":49,"order":49,"actions":[{"uid":"410400201:49:1","speaker":"???","text":"Hyaah!!","pose":10530201,"background":"","item":"","illustration":"","speaker_zh":"？？？","text_zh":"哈！！"}]},{"id":50,"order":50,"actions":[{"uid":"410400201:50:1","speaker":"Monster","text":"GRRRRAAARGH!","pose":1,"background":"","item":"","illustration":"","speaker_zh":"怪物","text_zh":"咕噜咕噜！"}]},{"id":51,"order":51,"actions":[{"uid":"410400201:51:1","speaker":"Kirito","text":"Huh?","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"咦？"},{"uid":"410400201:51:2","speaker":"Asuna","text":"","pose":10020911,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400201:51:3","speaker":"Yui","text":"","pose":20090208,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":52,"order":52,"actions":[{"uid":"410400201:52:1","speaker":"???","text":"...","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"？？？","text_zh":"..."}]},{"id":53,"order":53,"actions":[{"uid":"410400201:53:1","speaker":"Kirito","text":"Y-You...","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"你、你……"},{"uid":"410400201:53:2","speaker":"Asuna","text":"","pose":10020911,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400201:53:3","speaker":"Yui","text":"","pose":20090208,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":54,"order":54,"actions":[{"uid":"410400201:54:1","speaker":"Kirito","text":"You saved me...\nWho are you?","pose":10011505,"background":"bg_04_field_flower_snow","item":"","illustration":"","speaker_zh":"桐人","text_zh":"你救了我……你是谁？"},{"uid":"410400201:54:2","speaker":"Asuna","text":"","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400201:54:3","speaker":"Yui","text":"","pose":20090203,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":55,"order":55,"actions":[{"uid":"410400201:55:1","speaker":"???","text":"...","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"？？？","text_zh":"..."}]},{"id":56,"order":56,"actions":[{"uid":"410400201:56:1","speaker":"Kirito","text":"","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410400201:56:2","speaker":"Yui","text":"","pose":20090203,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""},{"uid":"410400201:56:3","speaker":"Asuna","text":"Who's the one who stepped\nin to save Kirito...?","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"谁是介入拯救桐人的人……？"}]},{"id":57,"order":57,"actions":[{"uid":"410400201:57:1","speaker":"Sinon","text":"It looked like a guy. Probably\njust a little older than Kirito.","pose":10040202,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"看起来像个男人。可能只比桐人旧一点。"},{"uid":"410400201:57:2","speaker":"Leafa","text":"","pose":10030102,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":58,"order":58,"actions":[{"uid":"410400201:58:1","speaker":"Leafa","text":"And in that blue armor...\ndidn't he look a little\nlike Alice to you?","pose":10030102,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"还有那身蓝色铠甲……你看他是不是有点像爱丽丝？"},{"uid":"410400201:58:2","speaker":"Sinon","text":"","pose":10040202,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":59,"order":59,"actions":[{"uid":"410400201:59:1","speaker":"Amayori","text":"Grruugh!","pose":2,"background":"","item":"","illustration":"","speaker_zh":"雨缘","text_zh":"呜呜！"},{"uid":"410400201:59:2","speaker":"Alice","text":"","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":60,"order":60,"actions":[{"uid":"410400201:60:1","speaker":"Alice","text":"Looks like we've cleaned\nout this area.","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"看来我们已经把这片区域清理干净了。"}]},{"id":61,"order":61,"actions":[{"uid":"410400201:61:1","speaker":"Alice","text":"Hm...? Who's that?","pose":10540108,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"嗯……？那是谁？"}]},{"id":62,"order":62,"actions":[{"uid":"410400201:62:1","speaker":"???","text":"My name is...","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"？？？","text_zh":"我叫……"}]},{"id":63,"order":63,"actions":[{"uid":"410400201:63:1","speaker":"???","text":"Eugeo Synthesis Thirty-Two....","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"？？？","text_zh":"尤吉欧综合三十二...."}]},{"id":64,"order":64,"actions":[{"uid":"410400201:64:1","speaker":"Kirito","text":"Eugeo Synth-e-what?","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"尤吉欧合成电子什么？"},{"uid":"410400201:64:2","speaker":"Asuna","text":"","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400201:64:3","speaker":"Yui","text":"","pose":20090203,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":65,"order":65,"actions":[{"uid":"410400201:65:1","speaker":"Alice","text":"...!","pose":10540108,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"...!"},{"uid":"410400201:65:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":66,"order":66,"actions":[{"uid":"410400201:66:1","speaker":"Alice","text":"Wh-What did you just say?\nSynthesis Thirty-Two?!","pose":10540108,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"你、你刚刚说什么？合成三十二？！"}]},{"id":67,"order":67,"actions":[{"uid":"410400201:67:1","speaker":"Alice","text":"Does that mean you're a new\nIntegrity Knight?","pose":10540108,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"也就是说你是新的整合骑士了？"}]},{"id":68,"order":68,"actions":[{"uid":"410400201:68:1","speaker":"Asuna","text":"So, then...Eugeo and Alice\nalready know each other?","pose":10020911,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"那么……尤吉欧和爱丽丝已经认识了？"},{"uid":"410400201:68:2","speaker":"Kirito","text":"","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410400201:68:3","speaker":"Yui","text":"","pose":20090208,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":69,"order":69,"actions":[{"uid":"410400201:69:1","speaker":"Alice","text":"No. I've never seen\nthis man before...","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"没有。我以前从未见过这个人..."},{"uid":"410400201:69:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":70,"order":70,"actions":[{"uid":"410400201:70:1","speaker":"Sinon","text":"Wait. Didn't you say that the\ngoddess Urdr was putting together\na band of able warriors?","pose":10040202,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"等等。你不是说女神乌尔德正在组建一支精干的战士队伍吗？"},{"uid":"410400201:70:2","speaker":"Leafa","text":"","pose":10030102,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":71,"order":71,"actions":[{"uid":"410400201:71:1","speaker":"Alice","text":"Oh...! Then this Integrity Knight\nmust be the second one that Urdr\nsent on this mission?","pose":10540108,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"哦……！那么这个整合骑士一定是乌尔德派出的第二个执行这次任务的吗？"},{"uid":"410400201:71:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":72,"order":72,"actions":[{"uid":"410400201:72:1","speaker":"Eugeo","text":"What... What are\nyou talking about?","pose":10530202,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"什么……你在说什么？"}]},{"id":73,"order":73,"actions":[{"uid":"410400201:73:1","speaker":"Eugeo","text":"I'm sorry...\nMy memory's a bit foggy.","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"对不起……我的记忆有点模糊了。"}]},{"id":74,"order":74,"actions":[{"uid":"410400201:74:1","speaker":"Eugeo","text":"But I know I have to protect\nthe one who accepted me...\nMother...?","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"但我知道我必须保护接受我的人……妈妈……？"}]},{"id":75,"order":75,"actions":[{"uid":"410400201:75:1","speaker":"Eugeo","text":"No, that's not it... But there's\nan important person I'm\nsupposed to protect.","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"不，不是这样的……但是我有一个重要的人要保护。"}]},{"id":76,"order":76,"actions":[{"uid":"410400201:76:1","speaker":"Eugeo","text":"And I am...an Integrity Knight.\nEugeo Synthesis Thirty-Two.","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"而我是……整合骑士。 尤吉欧合成三十二．"},{"uid":"410400201:76:2","speaker":"Alice","text":"","pose":10540108,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":77,"order":77,"actions":[{"uid":"410400201:77:1","speaker":"???","text":"...","pose":2,"background":"bg_white","item":"","illustration":"","speaker_zh":"？？？","text_zh":"..."},{"uid":"410400201:77:2","speaker":"Eugeo","text":"","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":78,"order":78,"actions":[{"uid":"410400201:78:1","speaker":"???","text":"That's right... Go on...","pose":2,"background":"","item":"","illustration":"","speaker_zh":"？？？","text_zh":"是啊……继续……"}]},{"id":79,"order":79,"actions":[{"uid":"410400201:79:1","speaker":"???","text":"Remove Core Protection...","pose":2,"background":"","item":"","illustration":"","speaker_zh":"？？？","text_zh":"解除核心保护..."}]},{"id":80,"order":80,"actions":[{"uid":"410400201:80:1","speaker":"???","text":"Welcome...\nto eternal stagnation...","pose":2,"background":"","item":"","illustration":"","speaker_zh":"？？？","text_zh":"欢迎……来到永恒的停滞……"}]},{"id":81,"order":81,"actions":[{"uid":"410400201:81:1","speaker":"???","text":"Eugeo...","pose":2,"background":"","item":"","illustration":"","speaker_zh":"？？？","text_zh":"尤吉欧..."}]},{"id":82,"order":82,"actions":[{"uid":"410400201:82:1","speaker":"Eugeo","text":"...I am...","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"……我是……"}]},{"id":83,"order":83,"actions":[{"uid":"410400201:83:1","speaker":"Eugeo","text":"...","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"..."}]},{"id":84,"order":84,"actions":[{"uid":"410400201:84:1","speaker":"Eugeo","text":"What is this? It's like a world\nof hazy light...","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"这是什么？仿佛进入了一个光影朦胧的世界……"}]},{"id":85,"order":85,"actions":[{"uid":"410400201:85:1","speaker":"Eugeo","text":"Where did they go? Maybe if I keep\nwalking this way...I can make\nit back...","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"他们去哪儿了？也许如果我继续这样走……我可以回来……"}]},{"id":86,"order":86,"actions":[{"uid":"410400201:86:1","speaker":"Urdr","text":"You...!","pose":20330107,"background":"bg_18_mountain","item":"","illustration":"","speaker_zh":"乌尔德","text_zh":"你……！"},{"uid":"410400201:86:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":87,"order":87,"actions":[{"uid":"410400201:87:1","speaker":"Eugeo","text":"Thank goodness, I made it back...","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"谢天谢地，我回来了……"}]},{"id":88,"order":88,"actions":[{"uid":"410400201:88:1","speaker":"Eugeo","text":"Wait. No... You're not the one\nI need to protect...! Who...\nare you?","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"等等。不……你不是我需要保护的人……！你……是谁？"}]},{"id":89,"order":89,"actions":[{"uid":"410400201:89:1","speaker":"Kirito","text":"So that's the only thing\nyou can remember?","pose":10011502,"background":"bg_04_field_flower_snow","item":"","illustration":"","speaker_zh":"桐人","text_zh":"所以你就只记得这个了？"},{"uid":"410400201:89:2","speaker":"Asuna","text":"","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400201:89:3","speaker":"Yui","text":"","pose":20090203,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":90,"order":90,"actions":[{"uid":"410400201:90:1","speaker":"Eugeo","text":"That's right.","pose":10530206,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"是啊。"},{"uid":"410400201:90:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":91,"order":91,"actions":[{"uid":"410400201:91:1","speaker":"Kirito","text":"So you've really lost all your\nmemories? What could have\nhappened to you...?","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"所以你真的失去了所有的记忆吗？你可能发生了什么……？"},{"uid":"410400201:91:2","speaker":"Asuna","text":"","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400201:91:3","speaker":"Yui","text":"","pose":20090203,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":92,"order":92,"actions":[{"uid":"410400201:92:1","speaker":"Asuna","text":"Alice, you don't know who Eugeo\nis either, do you?","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"爱丽丝，你也不知道尤吉欧是谁吧？"},{"uid":"410400201:92:2","speaker":"Yui","text":"","pose":20090203,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":93,"order":93,"actions":[{"uid":"410400201:93:1","speaker":"Alice","text":"No... He must be another one\nthe goddess chose as a helper.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"不……他一定是女神选的另一个帮手。"},{"uid":"410400201:93:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":94,"order":94,"actions":[{"uid":"410400201:94:1","speaker":"Alice","text":"Even I don't know a Thirty-Two...\nI'd like to get to the bottom of\nthis, but we don't have time now.","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"连我都不认识三十二……我很想查个水落石出，但现在没时间。"}]},{"id":95,"order":95,"actions":[{"uid":"410400201:95:1","speaker":"Amayori","text":"Ggruuuruu!","pose":2,"background":"","item":"","illustration":"","speaker_zh":"雨缘","text_zh":"咕咕咕！"}]},{"id":96,"order":96,"actions":[{"uid":"410400201:96:1","speaker":"Kirito","text":"...!","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"...!"},{"uid":"410400201:96:2","speaker":"Asuna","text":"","pose":10020911,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400201:96:3","speaker":"Yui","text":"","pose":20090208,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":97,"order":97,"actions":[{"uid":"410400201:97:1","speaker":"Monster","text":"GRAAUUGH!!","pose":1,"background":"","item":"","illustration":"","speaker_zh":"怪物","text_zh":"吼啊啊！"}]},{"id":98,"order":98,"actions":[{"uid":"410400201:98:1","speaker":"Asuna","text":"More monsters?!","pose":10020911,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"更多怪物？！"},{"uid":"410400201:98:2","speaker":"Yui","text":"","pose":20090208,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":99,"order":99,"actions":[{"uid":"410400201:99:1","speaker":"Leafa","text":"It looks like we're up against\nthe main forces this time!","pose":10030102,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"看来这次要面对主力了！"},{"uid":"410400201:99:2","speaker":"Sinon","text":"","pose":10040202,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":""}]},{"id":100,"order":100,"actions":[{"uid":"410400201:100:1","speaker":"Sinon","text":"We can worry about this guy's\nbackstory after we take care\nof these guys!","pose":10040202,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"解决了这些家伙，我们就可以关心这家伙的来历了！"}]},{"id":101,"order":101,"actions":[{"uid":"410400201:101:1","speaker":"Kirito","text":"You said it!\nStay back, Eugeo!\nWe've got this!","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"你说的是！退后一步，尤吉欧！我们有这个！"},{"uid":"410400201:101:2","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400201:101:3","speaker":"Yui","text":"","pose":20090207,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":102,"order":102,"actions":[{"uid":"410400201:102:1","speaker":"Eugeo","text":"No! I'll fight too!","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"不！我也要战斗！"},{"uid":"410400201:102:2","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":103,"order":103,"actions":[{"uid":"410400201:103:1","speaker":"Kirito","text":"What?","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"什么？"},{"uid":"410400201:103:2","speaker":"Asuna","text":"","pose":10020911,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400201:103:3","speaker":"Yui","text":"","pose":20090208,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":104,"order":104,"actions":[{"uid":"410400201:104:1","speaker":"Eugeo","text":"You saw me back there, didn't\nyou? I'm no weakling.","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"你在后面看到我了，不是吗？我不是弱者。"},{"uid":"410400201:104:2","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":105,"order":105,"actions":[{"uid":"410400201:105:1","speaker":"Eugeo","text":"And it's not just that. Something\nabout fighting alongside you makes\nme feel...happy.","pose":10530204,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"而且还不仅如此。与你并肩作战让我感到……快乐。"}]},{"id":106,"order":106,"actions":[{"uid":"410400201:106:1","speaker":"Eugeo","text":"I just...","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"我只是……"}]},{"id":107,"order":107,"actions":[{"uid":"410400201:107:1","speaker":"Kirito","text":"...Alright! I understand!","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"……好吧！我明白！"},{"uid":"410400201:107:2","speaker":"Asuna","text":"","pose":10020907,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":108,"order":108,"actions":[{"uid":"410400201:108:1","speaker":"Kirito","text":"You can lend me a hand!","pose":10011507,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"你可以帮我一下！"},{"uid":"410400201:108:2","speaker":"ユイ","text":"","pose":20090207,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":109,"order":109,"actions":[{"uid":"410400201:109:1","speaker":"Eugeo","text":"Okay!","pose":10530207,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"好！"},{"uid":"410400201:109:2","speaker":"Alice","text":"","pose":10540107,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":110,"order":110,"actions":[{"uid":"410400201:110:1","speaker":"Alice","text":"Just like the goddess said...\nit's a Divine Object!","pose":10540108,"background":"bg_04_field_flower_snow","item":"item_event_sacred_treasure","illustration":"","speaker_zh":"爱丽丝","text_zh":"正如女神所说……是神器！"},{"uid":"410400201:110:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":111,"order":111,"actions":[{"uid":"410400201:111:1","speaker":"Kirito","text":"Huh? That's what Urdr wanted\nyou to find?","pose":10011508,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"啊？这就是乌尔德想让你找到的东西？"},{"uid":"410400201:111:2","speaker":"Asuna","text":"","pose":10020911,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""},{"uid":"410400201:111:3","speaker":"Yui","text":"","pose":20090208,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":112,"order":112,"actions":[{"uid":"410400201:112:1","speaker":"Alice","text":"Yes. One down, six to go.","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"是的。已落一，还剩六。"},{"uid":"410400201:112:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":113,"order":113,"actions":[{"uid":"410400201:113:1","speaker":"Asuna","text":"So these monsters had\nstolen it! Good thing\nwe got it back.","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"原来是这些怪物偷走了它！还好我们把它找回来了。"},{"uid":"410400201:113:2","speaker":"Kirito","text":"","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410400201:113:3","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":114,"order":114,"actions":[{"uid":"410400201:114:1","speaker":"Sinon","text":"It seems that we defeated all\nthe monsters in this area in\nthat battle, too.","pose":10040204,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"看来我们在那次战斗中也打败了这个区域的所有怪物。"},{"uid":"410400201:114:2","speaker":"Leafa","text":"","pose":10030104,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":115,"order":115,"actions":[{"uid":"410400201:115:1","speaker":"Yui","text":"Yes. It doesn't look like any\nmore are going to spawn here.","pose":20090204,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"是的。看起来不会再有任何东西会在这里产生。"},{"uid":"410400201:115:2","speaker":"Kirito","text":"","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410400201:115:3","speaker":"Asuna","text":"","pose":10020904,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":116,"order":116,"actions":[{"uid":"410400201:116:1","speaker":"Yui","text":"And this notification says we've\ncompleted the quest.","pose":20090204,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":"这个通知表明我们已经完成了任务。"}]},{"id":117,"order":117,"actions":[{"uid":"410400201:117:1","speaker":"Eugeo","text":"What a complicated dialect\nyou all speak here...","pose":10530202,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"你们这里的方言好复杂啊……"},{"uid":"410400201:117:2","speaker":"Alice","text":"","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":118,"order":118,"actions":[{"uid":"410400201:118:1","speaker":"Kirito","text":"Oh! Sorry... Allow me to\nexplain...um, again.","pose":100115032,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"哦！抱歉...请允许我解释一下...嗯，再一次。"},{"uid":"410400201:118:2","speaker":"Yui","text":"","pose":20090203,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""},{"uid":"410400201:118:3","speaker":"Asuna","text":"","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":119,"order":119,"actions":[{"uid":"410400201:119:1","speaker":"Leafa","text":"...Hey, Kirito.","pose":10030102,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"...嘿，桐人。"},{"uid":"410400201:119:2","speaker":"Kirito","text":"","pose":100115032,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""}]},{"id":120,"order":120,"actions":[{"uid":"410400201:120:1","speaker":"Kirito","text":"Wh-What? What is it, Sugu?\nYeesh, don't pull my ears\nwhen you whisper...","pose":100115032,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"什、什么？这是什么，小直？是的，你低声说话时别拉我的耳朵……"}]},{"id":121,"order":121,"actions":[{"uid":"410400201:121:1","speaker":"Leafa","text":"NPCs aren't supposed to hang\naround after you finish an event\nquest, right?","pose":10030102,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"完成活动任务后NPC不应该在附近徘徊，对吗？"}]},{"id":122,"order":122,"actions":[{"uid":"410400201:122:1","speaker":"Kirito","text":"Yeah... But I don't think\nthose two are NPCs.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"是啊……不过我不认为那两个是NPC。"}]},{"id":123,"order":123,"actions":[{"uid":"410400201:123:1","speaker":"Leafa","text":"Are you sure...? But wait! We're\nnot finished. There are still six\nDivine Objects left, aren't there?","pose":10030102,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"你确定……？但是等等！我们还没有完成。神器还剩下六件不是吗？"}]},{"id":124,"order":124,"actions":[{"uid":"410400201:124:1","speaker":"Alice","text":"What are you two\nwhispering about?","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"你们两个在窃窃私语什么呢？"},{"uid":"410400201:124:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":125,"order":125,"actions":[{"uid":"410400201:125:1","speaker":"Kirito","text":"Oh! Uh, nothing!\nNothing at all. Hehe...","pose":100115032,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"哦！呃，没什么！什么都没有。呵呵..."},{"uid":"410400201:125:2","speaker":"Leafa","text":"","pose":100301032,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":126,"order":126,"actions":[{"uid":"410400201:126:1","speaker":"Asuna","text":"Hahaha! Anyway, we couldn't\nhave made it back there\nwithout your help!","pose":100209042,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"哈哈哈！不管怎样，如果没有你的帮助，我们不可能回到那里！"},{"uid":"410400201:126:2","speaker":"Kirito","text":"","pose":10011504,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410400201:126:3","speaker":"Yui","text":"","pose":20090204,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":127,"order":127,"actions":[{"uid":"410400201:127:1","speaker":"Sinon","text":"Yeah! If it wasn't for you two,\nwe'd all be monster chow right\nnow!","pose":10040204,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"是啊！如果没有你们两个，我们现在都变成怪物了！"},{"uid":"410400201:127:2","speaker":"Leafa","text":"","pose":10030104,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":128,"order":128,"actions":[{"uid":"410400201:128:1","speaker":"Alice","text":"I made a promise to recover all of\nthe Divine Objects... I will\nremain in this realm until I do.","pose":10540105,"background":"bg_04_field_flower_snow","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"我承诺要收回所有的神器...我会一直留在这个领域，直到收回为止。"},{"uid":"410400201:128:2","speaker":"Eugeo","text":"","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":129,"order":129,"actions":[{"uid":"410400201:129:1","speaker":"Kirito","text":"I see...","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我明白了……"},{"uid":"410400201:129:2","speaker":"Yui","text":"","pose":20090205,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""},{"uid":"410400201:129:3","speaker":"Asuna","text":"","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":130,"order":130,"actions":[{"uid":"410400201:130:1","speaker":"Eugeo","text":"I'll stay here too. I gave\nthat goddess my word as\nan Integrity Knight.","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"我也留在这里。我以整合骑士的身份向这位女神发誓。"},{"uid":"410400201:130:2","speaker":"Alice","text":"","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":""}]},{"id":131,"order":131,"actions":[{"uid":"410400201:131:1","speaker":"Eugeo","text":"I want to see that promise through.","pose":10530205,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":"我想兑现这个承诺。"}]},{"id":132,"order":132,"actions":[{"uid":"410400201:132:1","speaker":"Alice","text":"...","pose":10540105,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"..."}]},{"id":133,"order":133,"actions":[{"uid":"410400201:133:1","speaker":"Asuna","text":"Well, I guess you two will need\nsomewhere to stay.","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"嗯，我猜你们两个需要找地方住。"},{"uid":"410400201:133:2","speaker":"Kirito","text":"","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":""},{"uid":"410400201:133:3","speaker":"Yui","text":"","pose":20090203,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":134,"order":134,"actions":[{"uid":"410400201:134:1","speaker":"Asuna","text":"Kirito, I thought we might bring\nthem to stay in our log cabin.\nWhat do you think?","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"桐人，我想我们可以带他们住在我们的小木屋里。你怎么认为？"}]},{"id":135,"order":135,"actions":[{"uid":"410400201:135:1","speaker":"Kirito","text":"Ah... Yeah, sure.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"啊……是啊，当然。"},{"uid":"410400201:135:2","speaker":"Yui","text":"","pose":20090203,"background":"","item":"","illustration":"","speaker_zh":"结衣","text_zh":""}]},{"id":136,"order":136,"actions":[{"uid":"410400201:136:1","speaker":"Sinon","text":"Now that we've taken out the\nenemies in this lower realm, we\nshould head back to the surface.","pose":10040205,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"现在我们已经消灭了下界的敌人，我们该返回地表了。"},{"uid":"410400201:136:2","speaker":"Leafa","text":"","pose":10030105,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":137,"order":137,"actions":[{"uid":"410400201:137:1","speaker":"Alice","text":"The surface... You mentioned that\nbefore, didn't you?","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"表面……你之前也提过吧？"},{"uid":"410400201:137:2","speaker":"Eugeo","text":"","pose":10530202,"background":"","item":"","illustration":"","speaker_zh":"尤吉欧","text_zh":""}]},{"id":138,"order":138,"actions":[{"uid":"410400201:138:1","speaker":"Alice","text":"Does that mean this world\nreally is underground?","pose":10540102,"background":"","item":"","illustration":"","speaker_zh":"爱丽丝","text_zh":"也就是说这个世界真的是地下吗？"}]},{"id":139,"order":139,"actions":[{"uid":"410400201:139:1","speaker":"Sinon","text":"Yes, that's right. Maybe I should\nexplain from the beginning.","pose":10040205,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"是的，没错。也许我应该从头开始解释。"},{"uid":"410400201:139:2","speaker":"Leafa","text":"","pose":10030105,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":""}]},{"id":140,"order":140,"actions":[{"uid":"410400201:140:1","speaker":"Sinon","text":"Alice, Eugeo? Can you\ncome over here?","pose":10040204,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"爱丽丝，尤吉欧？你能过来一下吗？"}]},{"id":141,"order":141,"actions":[{"uid":"410400201:141:1","speaker":"Leafa","text":"Oh! Let me help! I've got a big,\nsimple map of everywhere\nin ALO on me right now.","pose":10030104,"background":"","item":"","illustration":"","speaker_zh":"莉法","text_zh":"哦！让我帮忙吧！我现在手上有一张大而简单的地图，标出了 ALO 中的所有地方。"}]},{"id":142,"order":142,"actions":[{"uid":"410400201:142:1","speaker":"Sinon","text":"Thanks! That'd be a great help.","pose":10040204,"background":"","item":"","illustration":"","speaker_zh":"诗乃","text_zh":"谢谢！那将是一个很大的帮助。"}]},{"id":143,"order":143,"actions":[{"uid":"410400201:143:1","speaker":"Kirito","text":"...","pose":10011502,"background":"bg_13_home_lounge_sunset","item":"","illustration":"","speaker_zh":"桐人","text_zh":"..."},{"uid":"410400201:143:2","speaker":"Asuna","text":"","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":""}]},{"id":144,"order":144,"actions":[{"uid":"410400201:144:1","speaker":"Asuna","text":"Who are those two...? Or maybe\nI should say \"what\" are they...","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"那两个人是谁……？或者也许我应该说“它们是什么”......"}]},{"id":145,"order":145,"actions":[{"uid":"410400201:145:1","speaker":"Kirito","text":"They both say that a bright light\nbrought them here. Maybe\nthey came out of Urdr's spring.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"他们都说是一道明亮的光把他们带到了这里。也许他们是从乌尔德的春天里出来的。"}]},{"id":146,"order":146,"actions":[{"uid":"410400201:146:1","speaker":"Kirito","text":"That would mean they're from a\nlower realm than Jotunheimr.\nMaybe Nibelheim?","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"那就说明他们来自比幽兹海姆更低的境界。也许尼福尔海姆？"}]},{"id":147,"order":147,"actions":[{"uid":"410400201:147:1","speaker":"Asuna","text":"But Nibelheim is the home of the\nFrost Giants. There's nothing\nthere but icy wastelands...","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"但是尼福尔海姆是冰霜巨人的主场。那里除了冰冷的荒原什么也没有……"}]},{"id":148,"order":148,"actions":[{"uid":"410400201:148:1","speaker":"Asuna","text":"Based on what she's told us so\nfar, that doesn't sound like\nAlice's world to me.","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"根据她目前告诉我们的情况，我觉得那不像是爱丽丝的世界。"}]},{"id":149,"order":149,"actions":[{"uid":"410400201:149:1","speaker":"Kirito","text":"I guess so. She said that there's\na peaceful Human Empire and a Dark\nTerritory full of their enemies.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我想是的。她说这里有一个和平的人界和一个充满敌人的黑暗领域。"}]},{"id":150,"order":150,"actions":[{"uid":"410400201:150:1","speaker":"Kirito","text":"That's definitely not\nNibelheim, then...","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"那肯定不是尼福尔海姆，那么……"}]},{"id":151,"order":151,"actions":[{"uid":"410400201:151:1","speaker":"Kirito","text":"It's almost as though they came\nfrom a world that we don't even\nknow about.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"就好像他们来自一个我们根本不知道的世界。"}]},{"id":152,"order":152,"actions":[{"uid":"410400201:152:1","speaker":"Asuna","text":"I get that same feeling. It isn't\neven like they're from another\nvirtual world.","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"我也有同样的感觉。他们甚至不像来自另一个虚拟世界。"}]},{"id":153,"order":153,"actions":[{"uid":"410400201:153:1","speaker":"Asuna","text":"They act like they're from a\ncompletely different reality\nfrom us...","pose":10020902,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"他们表现得就像是来自与我们完全不同的现实……"}]},{"id":154,"order":154,"actions":[{"uid":"410400201:154:1","speaker":"Kirito","text":"Totally. And with responses as\ncomplex as theirs, they're almost\nindistinguishable from players.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"完全可以。由于响应与他们的一样复杂，它们几乎与玩家没有区别。"}]},{"id":155,"order":155,"actions":[{"uid":"410400201:155:1","speaker":"Kirito","text":"If that's the work of artificial\nintelligence, it's beyond anything\nI've ever seen before.","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"如果这就是人工智能的作品，那它是我以前从未见过的。"}]},{"id":156,"order":156,"actions":[{"uid":"410400201:156:1","speaker":"Kirito","text":"How many times have we had\nvisitors wandering in from some\nother world or timeline?","pose":10011502,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"有多少次有访客从其他世界或时间线徘徊而来？"}]},{"id":157,"order":157,"actions":[{"uid":"410400201:157:1","speaker":"Asuna","text":"Ahaha! You have a point.","pose":10020904,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"啊哈哈！你说得有道理。"}]},{"id":158,"order":158,"actions":[{"uid":"410400201:158:1","speaker":"Asuna","text":"Well, they could be an experimental\nplayer-simulation... But let's go\nwith this explanation for now.","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"嗯，它们可能是一个实验性的玩家模拟……但我们现在就按这个解释吧。"}]},{"id":159,"order":159,"actions":[{"uid":"410400201:159:1","speaker":"Kirito","text":"So we assume they're living,\nbreathing humans who wandered here\nfrom another world? Okay...","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"所以我们假设他们是从另一个世界漂泊到这里的活生生的人类？好吧..."}]},{"id":160,"order":160,"actions":[{"uid":"410400201:160:1","speaker":"Kirito","text":"Because no matter how you look at\nit, they're people in this world,\nand right now they need our help.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"因为无论怎么看，他们都是这个世界上的人，现在他们需要我们的帮助。"}]},{"id":161,"order":161,"actions":[{"uid":"410400201:161:1","speaker":"Asuna","text":"Right!","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"对啊！"}]},{"id":162,"order":162,"actions":[{"uid":"410400201:162:1","speaker":"Kirito","text":"Besides...isn't that the\ncoolest thing ever?","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"而且……这不是最酷的事情吗？"}]},{"id":163,"order":163,"actions":[{"uid":"410400201:163:1","speaker":"Asuna","text":"What?","pose":10020911,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"什么？"}]},{"id":164,"order":164,"actions":[{"uid":"410400201:164:1","speaker":"Kirito","text":"The fact that we even met these\ntwo... Doesn't it feel like a\nmiracle to you?","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我们竟然见到了这两个人……你不觉得这是一个奇迹吗？"}]},{"id":165,"order":165,"actions":[{"uid":"410400201:165:1","speaker":"Kirito","text":"Fighting alongside these berserk\nwarriors from another world...","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"与来自异世界的狂暴战士并肩作战……"}]},{"id":166,"order":166,"actions":[{"uid":"410400201:166:1","speaker":"Kirito","text":"This is the kind of experience you\ncould only access through a\nvirtual world!","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"这就是只有虚拟世界才能体验到的体验！"}]},{"id":167,"order":167,"actions":[{"uid":"410400201:167:1","speaker":"Asuna","text":"Ha ha! I know what you mean...\nSomething about them makes me\nfeel like we met for a reason.","pose":10020904,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"哈哈！我知道你的意思……他们身上的某些东西让我觉得我们的相遇是有原因的。"}]},{"id":168,"order":168,"actions":[{"uid":"410400201:168:1","speaker":"Kirito","text":"Yeah. And if there's just one\nthing I can say for sure\nabout those two...","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"嗯。如果关于这两个人只有一件事我可以肯定的话......"}]},{"id":169,"order":169,"actions":[{"uid":"410400201:169:1","speaker":"Kirito","text":"It's that they're good people!\nI want to help them both out\nsomehow.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"就是好人啊！我想以某种方式帮助他们俩。"}]},{"id":170,"order":170,"actions":[{"uid":"410400201:170:1","speaker":"Kirito","text":"I say we should team up with\nAlice and Eugeo for now.","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"我说我们现在应该和爱丽丝和尤吉欧组队。"}]},{"id":171,"order":171,"actions":[{"uid":"410400201:171:1","speaker":"Asuna","text":"Yeah, I think so too!\nThey're both really nice.","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"嗯，我也这么认为！他们俩都很好。"}]},{"id":172,"order":172,"actions":[{"uid":"410400201:172:1","speaker":"Asuna","text":"Until they return to their world,\nlet's do whatever we can to\nhelp them out.","pose":10020905,"background":"","item":"","illustration":"","speaker_zh":"亚丝娜","text_zh":"在他们回到自己的世界之前，我们尽我们所能帮助他们。"}]},{"id":173,"order":173,"actions":[{"uid":"410400201:173:1","speaker":"Kirito","text":"You bet!","pose":10011505,"background":"","item":"","illustration":"","speaker_zh":"桐人","text_zh":"你敢打赌！"}]}]};
